import sys

def count_leq(a, x):
    count = 0
    left = 0
    right = len(a) - 1

    while left < right:
        if a[left] + a[right] <= x:
            count += right - left
            left += 1
        else:
            right -= 1

    return count

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, i, f = data[0], data[1], data[2]
    a = data[3:3 + n]
    a.sort()

    ans = count_leq(a, f) - count_leq(a, i - 1)
    print(ans)

if __name__ == "__main__":
    main()
